// Longest subarray with sum <= k (all a[i] >= 0)
int longestWindow(int[] a, int k) {
    int l = 0, sum = 0, best = 0;
    for (int r = 0; r < a.length; r++) {
        sum += a[r];                 // expand
        while (sum > k) sum -= a[l++]; // shrink until valid
        best = Math.max(best, r - l + 1);
    }
    return best;
}
