int[] kLargest(int[] nums, int k) {
    PriorityQueue<Integer> pq = new PriorityQueue<>(); // min-heap
    for (int x : nums) {
        pq.offer(x);
        if (pq.size() > k) pq.poll(); // drop the smallest
    }
    int[] res = new int[pq.size()];
    for (int i = 0; i < res.length; i++) res[i] = pq.poll();
    return res;
}
