double myPow(double x, int n) {
    long e = n; // avoid overflow negating Integer.MIN_VALUE
    if (e < 0) { x = 1 / x; e = -e; }
    double res = 1;
    while (e > 0) {
        if ((e & 1) == 1) res *= x;
        x *= x;
        e >>= 1;
    }
    return res;
}
